import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO


class Group:
    def __init__(self, members: list[str]) -> None:
        if len(set(members)) != len(members):
            raise ValueError("Group members must be unique")
        self._members = list(members)
        self._balances = {member: 0 for member in members}  # cents
        self._expenses: list[dict] = []

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
        description: str = "",
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        try:
            value = Decimal(str(amount))
            if not value.is_finite() or value <= 0:
                raise ValueError("Amount must be positive and finite")
            cents = int((value * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        except (InvalidOperation, TypeError) as exc:
            raise ValueError("Invalid amount") from exc

        if participants is None:
            participants = self._members
        if not participants:
            raise ValueError("An expense must have at least one participant")
        if len(set(participants)) != len(participants):
            raise ValueError("Participants must be unique")
        if any(member not in self._balances for member in participants):
            raise ValueError("Participant is not a group member")

        share = cents // len(participants)
        for member in participants:
            if member != payer:
                self._balances[member] -= share
                self._balances[payer] += share

        self._expenses.append(
            {
                "payer": payer,
                "amount": amount,
                "participants": list(participants),
                "description": description,
            }
        )

    def expenses(self) -> list[dict]:
        return [
            {**expense, "participants": list(expense["participants"])}
            for expense in self._expenses
        ]

    def total_paid(self, member: str) -> float:
        if member not in self._balances:
            raise ValueError("Member is not a group member")
        total = sum(
            (Decimal(str(expense["amount"])) for expense in self._expenses
             if expense["payer"] == member),
            Decimal("0"),
        )
        return float(total)

    def export_csv(self) -> str:
        output = StringIO(newline="")
        writer = csv.writer(output, lineterminator="\n")
        writer.writerow(["payer", "amount", "participants", "description"])
        for expense in self._expenses:
            writer.writerow(
                [
                    expense["payer"],
                    expense["amount"],
                    ", ".join(expense["participants"]),
                    expense["description"],
                ]
            )
        return output.getvalue()

    def balances(self) -> dict[str, float]:
        return {member: cents / 100 for member, cents in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        debtors = sorted(
            ((member, -balance) for member, balance in self._balances.items() if balance < 0),
            key=lambda item: item[1],
            reverse=True,
        )
        creditors = sorted(
            ((member, balance) for member, balance in self._balances.items() if balance > 0),
            key=lambda item: item[1],
            reverse=True,
        )

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            debtor, debt = debtors[i]
            creditor, credit = creditors[j]
            payment = min(debt, credit)
            if payment < 100:
                # This remaining balance is written off.
                if debt < 100:
                    i += 1
                if credit < 100:
                    j += 1
                continue

            payments.append((debtor, creditor, payment / 100))
            debt -= payment
            credit -= payment
            if debt == 0:
                i += 1
            else:
                debtors[i] = (debtor, debt)
            if credit == 0:
                j += 1
            else:
                creditors[j] = (creditor, credit)

        return payments
